/* Lot 107: legacy sRGB interpolation past the ends (CSS Color 4 12.3) (generated by scripts/lot107_gen.py; expectations from scripts/lot107_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static wf_cssprop_t g_p;
static char g_o[320];

/* the interpolated text of two colours (currentcolor teal); the
 * return code is checked */
static const char *ip(const char *a, const char *b, int t, int code) {
    wf_cssprop_set_current(1, 0x008080u, 255);
    memset(&g_p, 0, sizeof(g_p));
    g_p.syntax = (unsigned char)wf_cssprop_syntax_parse("'<color>'", 9, &g_p);
    if (!g_p.syntax) return "BAD SYNTAX";
    if (wf_cssprop_interp(&g_p, a, b, t, g_o, (int)sizeof(g_o)) != code) return "BAD CODE";
    return g_o;
}

static void test_l107_interp_0(void) {
    TEST_ASSERT_EQUAL_STRING("rgb(0, 128, 255)", ip("rgb(0 0 0 / 0)", "rgb(none 128 255)", 30000, 2));
    TEST_ASSERT_EQUAL_STRING("rgba(200, 100, 0, 0.5)", ip("hwb(297deg 100% 2%)", "rgba(200, 100, 0, 0.5)", 10001, 2));
    TEST_ASSERT_EQUAL_STRING("rgba(244, 240, 200, 0.7667)", ip("#fff8", "palegoldenrod", 5000, 2));
    TEST_ASSERT_EQUAL_STRING("rgba(255, 0, 0, 0.125)", ip("rgb(255 0 0 / 0.25)", "rgba(200, 100, 0, 0.5)", -5000, 2));
    TEST_ASSERT_EQUAL_STRING("rgb(51, 26, 77)", ip("black", "rebeccapurple", 5000, 2));
    TEST_ASSERT_EQUAL_STRING("rgba(66, 0, 189, 0.775)", ip("rgba(0, 0, 255, 0.75)", "hsla(300, 100%, 25%, 0.8)", 5000, 2));
    TEST_ASSERT_EQUAL_STRING("rgb(17, 34, 51)", ip("#123", "#123", -20000, 2));
    TEST_ASSERT_EQUAL_STRING("rgba(238, 232, 170, 0)", ip("rgb(0 0 0 / 0)", "palegoldenrod", -3333, 2));
    TEST_ASSERT_EQUAL_STRING("rgba(255, 0, 0, 0.1883)", ip("rgb(0 0 0 / 0)", "#ff000020", 15000, 2));
    TEST_ASSERT_EQUAL_STRING("rgb(255, 255, 255)", ip("white", "blue", -1, 2));
    TEST_ASSERT_EQUAL_STRING("rgba(0, 102, 255, 0)", ip("rgb(255 0 0 / 0.25)", "rebeccapurple", -10000, 2));
    TEST_ASSERT_EQUAL_STRING("rgba(153, 220, 118, 0.8)", ip("palegoldenrod", "rgba(10, 200, 30, 0.6)", 5000, 2));
}

