    TEST_ASSERT_EQUAL_STRING("rgb(142, 235, 73)", ip("hsla(1.5708rad 50% 54.806% / 150%)", "hsla(300, 100%, 25%, 0.8)", -2500, 2));
    TEST_ASSERT_EQUAL_STRING("rgba(13, 242, 81, 0)", ip("hsl(120 50% 50%)", "#ff000020", 25000, 2));
    TEST_ASSERT_EQUAL_STRING("rgba(255, 0, 0, 0)", ip("#ff000020", "red", -5000, 2));
    TEST_ASSERT_EQUAL_STRING("rgb(255, 255, 196)", ip("hwb(238.62 95.358% 16%)", "rgba(0, 0, 255, 0.75)", -10000, 2));
